-- Catalog, permissions and audit. Apply with the Supabase migration owner.
create table public.brands(id uuid primary key default gen_random_uuid(),name text not null check(length(trim(name)) between 1 and 120),slug text not null unique check(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),name text not null check(length(trim(name)) between 1 and 120),slug text not null unique check(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),parent_id uuid references public.categories(id) on delete restrict,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(parent_id is distinct from id));
create table public.products(id uuid primary key default gen_random_uuid(),name text not null check(length(trim(name)) between 1 and 200),slug text not null unique check(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),description text not null default '',brand_id uuid not null references public.brands(id),category_id uuid not null references public.categories(id),species text not null check(species in ('Cachorros','Gatos','Ambos')),featured boolean not null default false,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.product_variants(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete restrict,sku text not null unique check(length(trim(sku)) between 1 and 80),barcode text check(barcode is null or barcode ~ '^[0-9]{8,14}$'),label text not null check(length(trim(label)) between 1 and 80),price_cents integer not null check(price_cents>=0),cost_cents integer not null default 0 check(cost_cents>=0),weight_grams integer not null default 0 check(weight_grams>=0),stock_quantity integer not null default 0 check(stock_quantity>=0),min_stock_quantity integer not null default 5 check(min_stock_quantity>=0),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.product_images(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,storage_path text not null unique check(storage_path !~ '(^/|\.\.)'),alt_text text not null check(length(trim(alt_text)) between 1 and 300),sort_order integer not null default 0 check(sort_order>=0),created_at timestamptz not null default now());
create table public.suppliers(id uuid primary key default gen_random_uuid(),name text not null check(length(trim(name)) between 1 and 160),contact_info text not null default '' check(length(contact_info)<=2000),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade,role text not null default 'admin' check(role='admin'),created_at timestamptz not null default now());
create table public.inventory_movements(id uuid primary key default gen_random_uuid(),variant_id uuid not null references public.product_variants(id) on delete restrict,type text not null check(type in ('entrada','saida')),quantity integer not null check(quantity>0),reason text not null check(length(trim(reason)) between 3 and 500),created_at timestamptz not null default now(),created_by uuid not null references auth.users(id) on delete restrict);
create table public.store_settings(id boolean primary key default true check(id),name text not null default 'Pet Piraju' check(length(trim(name)) between 1 and 80),slogan text not null default 'Cuidado que faz parte de casa.' check(length(slogan)<=160),updated_at timestamptz not null default now());
insert into public.store_settings(id) values(true);
create index products_category_idx on public.products(category_id);create index products_brand_idx on public.products(brand_id);create index products_active_featured_idx on public.products(active,featured);create index variants_product_idx on public.product_variants(product_id);create index images_product_sort_idx on public.product_images(product_id,sort_order);create index categories_parent_idx on public.categories(parent_id);create index inventory_variant_date_idx on public.inventory_movements(variant_id,created_at desc);create index inventory_created_by_idx on public.inventory_movements(created_by);
create unique index variants_sku_lower_unique on public.product_variants(lower(sku));
create function public.touch_updated_at() returns trigger language plpgsql set search_path=public,pg_temp as $$begin new.updated_at=clock_timestamp();return new;end$$;
do $$declare t text;begin foreach t in array array['brands','categories','products','product_variants','suppliers','store_settings'] loop execute format('create trigger touch_updated_at before update on public.%I for each row execute function public.touch_updated_at()',t);end loop;end$$;
create function public.is_admin() returns boolean language sql stable security definer set search_path=public,pg_temp as $$select exists(select 1 from public.admin_users where user_id=auth.uid() and role='admin')$$;
revoke all on function public.is_admin() from public;grant execute on function public.is_admin() to anon,authenticated;
-- Only the database owner may bootstrap administrators. No HTTP user can self-promote.
create procedure public.grant_admin(target_user uuid) language plpgsql security definer set search_path=public,pg_temp as $$begin insert into public.admin_users(user_id) values(target_user) on conflict(user_id) do nothing;end$$;
revoke all on procedure public.grant_admin(uuid) from public,anon,authenticated,service_role;
-- The owner retains implicit execution rights; never grant this procedure to API roles.
do $$declare t text;begin foreach t in array array['brands','categories','products','product_variants','product_images','suppliers','inventory_movements','admin_users','store_settings'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);end loop;end$$;
grant usage on schema public to anon,authenticated;
grant select on public.brands,public.categories,public.products,public.product_images,public.store_settings to anon,authenticated;
grant select(id,product_id,sku,barcode,label,price_cents,weight_grams,stock_quantity,min_stock_quantity,active,created_at,updated_at) on public.product_variants to anon,authenticated;
grant select on public.admin_users,public.suppliers,public.inventory_movements to authenticated;
grant insert,update,delete on public.brands,public.categories,public.suppliers to authenticated;
grant update on public.store_settings to authenticated;
create policy public_brands on public.brands for select using(active or public.is_admin());
create policy admin_brands on public.brands for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy public_categories on public.categories for select using(active or public.is_admin());
create policy admin_categories on public.categories for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy public_products on public.products for select using(public.is_admin() or (active and exists(select 1 from public.brands b where b.id=brand_id and b.active) and exists(select 1 from public.categories c where c.id=category_id and c.active)));
create policy public_variants on public.product_variants for select using(public.is_admin() or (active and exists(select 1 from public.products p where p.id=product_id)));
create policy public_images on public.product_images for select using(public.is_admin() or exists(select 1 from public.products p where p.id=product_id));
create policy admin_suppliers on public.suppliers for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy admin_inventory_read on public.inventory_movements for select to authenticated using(public.is_admin());
create policy own_admin_read on public.admin_users for select to authenticated using(user_id=auth.uid());
create policy settings_read on public.store_settings for select using(true);
create policy settings_update on public.store_settings for update to authenticated using(public.is_admin()) with check(public.is_admin());
-- No direct variant or movement writes, even by an authenticated administrator.
-- Definer RPCs perform authorization, row locking and append-only audit together.
create function public.audit_stock() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$declare delta integer;why text;begin delta=case when TG_OP='INSERT' then new.stock_quantity else new.stock_quantity-old.stock_quantity end;if delta<>0 then if not public.is_admin() then raise exception 'Administrador necessário' using errcode='42501';end if;why=current_setting('pet.inventory_reason',true);if why is null or length(trim(why))<3 then raise exception 'Motivo obrigatório';end if;insert into public.inventory_movements(variant_id,type,quantity,reason,created_by) values(new.id,case when delta>0 then 'entrada' else 'saida' end,abs(delta),why,auth.uid());end if;return new;end$$;
create trigger audit_stock after insert or update of stock_quantity on public.product_variants for each row execute function public.audit_stock();
create function public.adjust_inventory(p_variant_id uuid,p_type text,p_quantity integer,p_reason text) returns integer language plpgsql security definer set search_path=public,pg_temp as $$declare current_stock integer;new_stock integer;begin if not public.is_admin() then raise exception 'Administrador necessário' using errcode='42501';end if;if p_type not in ('entrada','saida') or p_type is null or p_quantity is null or p_quantity<=0 or p_reason is null or length(trim(p_reason)) not between 3 and 500 then raise exception 'Movimentação inválida';end if;select stock_quantity into current_stock from public.product_variants where id=p_variant_id for update;if not found then raise exception 'Variante não encontrada';end if;new_stock=current_stock+case when p_type='entrada' then p_quantity else -p_quantity end;if new_stock<0 then raise exception 'Estoque insuficiente';end if;perform set_config('pet.inventory_reason',trim(p_reason),true);update public.product_variants set stock_quantity=new_stock where id=p_variant_id;return new_stock;end$$;
create function public.admin_catalog() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin if not public.is_admin() then raise exception 'Administrador necessário' using errcode='42501';end if;return jsonb_build_object('products',coalesce((select jsonb_agg(to_jsonb(p) order by p.created_at desc) from public.products p),'[]'::jsonb),'variants',coalesce((select jsonb_agg(to_jsonb(v) order by v.created_at) from public.product_variants v),'[]'::jsonb),'images',coalesce((select jsonb_agg(to_jsonb(i) order by i.sort_order) from public.product_images i),'[]'::jsonb),'brands',coalesce((select jsonb_agg(to_jsonb(b) order by b.name) from public.brands b),'[]'::jsonb),'categories',coalesce((select jsonb_agg(to_jsonb(c) order by c.name) from public.categories c),'[]'::jsonb),'suppliers',coalesce((select jsonb_agg(to_jsonb(s) order by s.name) from public.suppliers s),'[]'::jsonb),'movements',coalesce((select jsonb_agg(to_jsonb(m)) from (select * from public.inventory_movements order by created_at desc limit 200) m),'[]'::jsonb),'settings',(select to_jsonb(s) from public.store_settings s));end$$;
create function public.save_product(payload jsonb) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$declare pid uuid;v jsonb;img jsonb;existing public.products%rowtype;vid uuid;old_stock integer;begin
if not public.is_admin() then raise exception 'Administrador necessário' using errcode='42501';end if;
if jsonb_array_length(payload->'variants') not between 1 and 30 or jsonb_array_length(payload->'images')>12 then raise exception 'Quantidade de variantes ou imagens inválida';end if;
pid=(payload->>'id')::uuid;select * into existing from public.products where id=pid for update;
if found then if (payload->>'updated_at')::timestamptz is distinct from existing.updated_at then raise exception 'Produto alterado por outro administrador. Recarregue antes de salvar.';end if;end if;
insert into public.products(id,name,slug,description,brand_id,category_id,species,featured,active) values(pid,payload->>'name',payload->>'slug',payload->>'description',(payload->>'brand_id')::uuid,(payload->>'category_id')::uuid,payload->>'species',(payload->>'featured')::boolean,(payload->>'active')::boolean) on conflict(id) do update set name=excluded.name,slug=excluded.slug,description=excluded.description,brand_id=excluded.brand_id,category_id=excluded.category_id,species=excluded.species,featured=excluded.featured,active=excluded.active;
for v in select * from jsonb_array_elements(payload->'variants') loop
vid=(v->>'id')::uuid;select stock_quantity into old_stock from public.product_variants where id=vid for update;
if found then if not exists(select 1 from public.product_variants where id=vid and product_id=pid) then raise exception 'Variante pertence a outro produto';end if;if old_stock<>(v->>'stock_quantity')::integer then raise exception 'Use o controle de estoque para alterar saldos existentes';end if;end if;
perform set_config('pet.inventory_reason','Estoque inicial no cadastro',true);
insert into public.product_variants(id,product_id,sku,barcode,label,price_cents,cost_cents,weight_grams,stock_quantity,min_stock_quantity,active) values(vid,pid,trim(v->>'sku'),nullif(v->>'barcode',''),v->>'label',(v->>'price_cents')::integer,(v->>'cost_cents')::integer,(v->>'weight_grams')::integer,(v->>'stock_quantity')::integer,(v->>'min_stock_quantity')::integer,(v->>'active')::boolean) on conflict(id) do update set sku=excluded.sku,barcode=excluded.barcode,label=excluded.label,price_cents=excluded.price_cents,cost_cents=excluded.cost_cents,weight_grams=excluded.weight_grams,min_stock_quantity=excluded.min_stock_quantity,active=excluded.active;
end loop;
-- Retain audit references; removing a variant means deactivating it.
update public.product_variants set active=false where product_id=pid and id not in(select (x->>'id')::uuid from jsonb_array_elements(payload->'variants') x);
delete from public.product_images where product_id=pid;
for img in select * from jsonb_array_elements(payload->'images') loop
if not exists(select 1 from storage.objects where bucket_id='product-images' and name=img->>'storage_path') then raise exception 'Imagem não encontrada no Storage';end if;
insert into public.product_images(product_id,storage_path,alt_text,sort_order) values(pid,img->>'storage_path',img->>'alt_text',(img->>'sort_order')::integer);
end loop;return pid;end$$;
revoke all on function public.adjust_inventory(uuid,text,integer,text),public.admin_catalog(),public.save_product(jsonb),public.audit_stock(),public.touch_updated_at() from public,anon,authenticated;
grant execute on function public.adjust_inventory(uuid,text,integer,text),public.admin_catalog(),public.save_product(jsonb) to authenticated;

